package Q3;
import javax.swing.*;import java.awt.*;
public class LibrarySearch extends JFrame{public LibrarySearch(){super("Campus Library Search");setLayout(new BorderLayout(8,8));JLabel title=new JLabel("Campus Library",SwingConstants.CENTER);title.setFont(title.getFont().deriveFont(20f));add(title,BorderLayout.NORTH);JPanel search=new JPanel(new FlowLayout(FlowLayout.LEFT));JTextField q=new JTextField(22);JComboBox<String>cat=new JComboBox<>(new String[]{"All","Books","Journals","Theses"});JButton go=new JButton("Search");search.add(q);search.add(cat);search.add(go);JPanel center=new JPanel(new BorderLayout());center.add(search,BorderLayout.NORTH);DefaultListModel<String>model=new DefaultListModel<>();JList<String>results=new JList<>(model);center.add(new JScrollPane(results),BorderLayout.CENTER);add(center,BorderLayout.CENTER);JPanel bottom=new JPanel(new FlowLayout());for(String s:new String[]{"Prev","Next","Reserve"})bottom.add(new JButton(s));JLabel status=new JLabel("Ready");JPanel south=new JPanel(new BorderLayout());south.add(bottom,BorderLayout.CENTER);south.add(status,BorderLayout.SOUTH);add(south,BorderLayout.SOUTH);go.addActionListener(e->{model.clear();model.addElement("Search: "+q.getText()+" ("+cat.getSelectedItem()+")");status.setText("1 result displayed (demo)");});setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(650,450);setLocationRelativeTo(null);}public static void main(String[]x){SwingUtilities.invokeLater(()->new LibrarySearch().setVisible(true));}}
